import React from "react";
import withNavigation from "../utils/withNavigation";
import LeftSlidebar from "./leftSlidebar";
import axiosInstance from "../configurations/instance";

class EventsList extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      events: [],
      selectedEvent: null,
      editEvent: null,
    };
  }

  componentDidMount() {
    axiosInstance
      .get("/event/all-events")
      .then((response) => {
        this.setState({ events: response.data });
      })
      .catch((error) => console.error("Ошибка при загрузке событий:", error));
  }

  handleView = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ selectedEvent: response.data, editEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleEdit = (id) => {
    axiosInstance
      .get(`/event/${id}`)
      .then((response) => {
        this.setState({ editEvent: response.data, selectedEvent: null });
      })
      .catch((error) => console.error("Ошибка при загрузке события:", error));
  };

  handleDelete = (id) => {
    axiosInstance
      .delete(`/event/${id}`)
      .then(() => {
        this.setState((prevState) => ({
          events: prevState.events.filter((event) => event.eventId !== id),
          selectedEvent: null,
          editEvent: null,
        }));
      })
      .catch((error) => console.error("Ошибка при удалении события:", error));
  };

  isEditableOrDeletable = (eventDate) => {
    const now = new Date();
    const eventStart = new Date(eventDate);
    return now < eventStart;
  };

  render() {
    const { events, selectedEvent, editEvent } = this.state;

    return (
      <div className="creating-page">
        <header className="main-header"></header>
        <div className="profile-page">
          <LeftSlidebar />
          <div className="content">
            <h1>Список событий</h1>
            <table className="event-table">
              <thead>
                <tr>
                  <th>№</th>
                  <th>Название</th>
                  <th>Время проведения</th>
                  <th>Действия</th>
                </tr>
              </thead>
              <tbody>
                {events.map((event, index) => (
                  <tr key={event.eventId}>
                    <td>{index + 1}</td>
                    <td>{event.eventName}</td>
                    <td>{new Date(event.eventDate).toLocaleDateString()}</td>
                    <td>
                      <button
                        className="check"
                        onClick={() => this.handleView(event.eventId)}
                      >
                        Просмотр
                      </button>
                      {this.isEditableOrDeletable(event.eventDate) && (
                        <>
                          <button
                            className="change"
                            onClick={() => this.handleEdit(event.eventId)}
                          >
                            Изменить
                          </button>
                          <button
                            className="delete"
                            onClick={() => this.handleDelete(event.eventId)}
                          >
                            Удалить
                          </button>
                        </>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {selectedEvent && (
              <div className="event-details">
                <h1>Детали события</h1>
                <div className="createForm">
                  <h3>Название мероприятия</h3>
                  <div>{selectedEvent.eventName}</div>

                  <h3>Тип мероприятия</h3>
                  <div>{selectedEvent.eventType}</div>

                  <h3>Дата проведения</h3>
                  <div>{new Date(selectedEvent.eventDate).toLocaleString()}</div>

                  <h3>Проверяющие</h3>
                  {selectedEvent.emailFields.map((email, index) => (
                    <div key={index}>{email}</div>
                  ))}

                  <h3>Участники</h3>
                  {selectedEvent.participants.map((participant, index) => (
                    <div key={index}>
                      <h4>Участник №{index + 1}</h4>
                      <p>ФИО: {participant.name}</p>
                      <p>ИИН: {participant.iin}</p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {editEvent && (
              <div className="createForm">
                <h1>Редактирование события</h1>
                <h3>Название мероприятия</h3>
                <input
                  type="text"
                  value={editEvent.eventName}
                  onChange={(e) =>
                    this.handleInputChange("eventName", e.target.value)
                  }
                />

                <h3>Тип мероприятия</h3>
                <select
                  value={editEvent.eventType}
                  onChange={(e) =>
                    this.handleInputChange("eventType", e.target.value)
                  }
                >
                  <option value="" disabled>
                    Выберите тип мероприятия
                  </option>
                  <option value="seminar">Семинар</option>
                  <option value="competition">Соревнования</option>
                  <option value="conference">Конференция</option>
                </select>

                <h3>Дата проведения</h3>
                <input
                  type="datetime-local"
                  value={new Date(editEvent.eventDate)
                    .toISOString()
                    .slice(0, 16)}
                  onChange={(e) =>
                    this.handleInputChange("eventDate", e.target.value)
                  }
                />

                <h3>Добавьте проверяющего(-их)</h3>
                {editEvent.emailFields.map((email, index) => (
                  <div key={index}>
                    <input
                      type="text"
                      value={email}
                      placeholder="Введите почту проверяющего"
                      onChange={(e) =>
                        this.handleEmailChange(index, e.target.value)
                      }
                    />
                  </div>
                ))}
                <button onClick={this.addEmailField}>Добавить проверяющего</button>

                <h3>Добавьте участника(-ов)</h3>
                {editEvent.participants.map((participant, index) => (
                  <div key={index}>
                    <h4>Участник №{index + 1}</h4>
                    <input
                      type="text"
                      value={participant.name}
                      placeholder="ФИО"
                      onChange={(e) =>
                        this.handleParticipantChange(
                          index,
                          "name",
                          e.target.value
                        )
                      }
                    />
                    <input
                      type="text"
                      value={participant.iin}
                      placeholder="ИИН"
                      onChange={(e) =>
                        this.handleParticipantChange(
                          index,
                          "iin",
                          e.target.value
                        )
                      }
                    />
                  </div>
                ))}
                <button onClick={this.addParticipant}>Добавить участника</button>
                <button className="add-button" onClick={this.handleUpdate}>
                  Сохранить
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default withNavigation(EventsList);
